<?php

/**
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class DatCierre extends BaseDatCierre
{

    public function setUp()
    {
        parent::setUp();
    }

    static public function BuscarCierreSubsistema($estructurasubsist)
    {
        try{
            $objDoctrine = Doctrine_Manager::getInstance();
            $conexionActual = $objDoctrine->getCurrentConnection();
            $query= "SELECT dc.*,dp.nombre as periodo,de.nombre as ejercicio from mod_datosmaestros.dat_cierre dc
                INNER JOIN mod_datosmaestros.dat_periodocontable dp ON dc.idperiodoactual=dp.idperiodo
                INNER JOIN mod_datosmaestros.dat_ejerciciocontable de ON dc.idejercicioactual=de.idejercicio";
            $where = "where dc.idestructurasubsist = $estructurasubsist";
            $result = $conexionActual->fetchAll($query." ".$where);
            return $result;
        }catch (Exception $e){
            throw $e;
        }
    }

    static public function tieneCierreDiario($idestructurasubsist)
    {
        try{
            $q = new Doctrine_Query();
            $result = $q->select("s.cierrediario")->from("DatCierre s")
                ->where("s.idestructurasubsist = ?", $idestructurasubsist)
                ->execute()
                ->toArray();
            return $result[0]['cierrediario'];
        }catch (Exception $e){
            throw $e;
        }
    }

}
